WITH transactions_by_account AS (SELECT account_id, SUM(amount) AS total_amount, ROUND(STDDEV(amount), 2) AS stddev_amount FROM transactions WHERE txn_type NOT IN ('FEE', 'REFUND', 'DEBIT') GROUP BY account_id) SELECT a.id, a.account_type, a.balance, tba.total_amount, tba.stddev_amount FROM accounts a LEFT JOIN transactions_by_account tba ON a.id = tba.account_id WHERE tba.total_amount >= 9000;
